//
//  GlassShellAcknowledgementsView.swift
//  Glass Power Tools — GlassShell
//
//  Every third-party component in the app and its licence, from Settings ▸ About. The list is
//  `Resources/Acknowledgements.json`, generated by `Tools/Licenses/generate-acknowledgements.py`
//  from the resolved packages, the vendored code and Mermaid's own package list; a licence that
//  asks for its text to travel with the product travels here.
//

import SwiftUI

/// One component and its licence texts, as the generator writes them.
struct GlassAcknowledgement: Decodable, Identifiable, Hashable {
    struct LicenceText: Decodable, Hashable {
        let title: String
        let body: String
    }

    let id: String
    let name: String
    let group: String
    let license: String
    let version: String?
    let revision: String?
    let source: String?
    let note: String?
    let texts: [LicenceText]

    /// A release number when there is one, otherwise the start of the commit.
    var versionLabel: String? {
        version ?? revision.map { String($0.prefix(12)) }
    }
}

enum GlassAcknowledgements {
    private struct File: Decodable { let components: [GlassAcknowledgement] }

    /// The order groups read in: the app's own capabilities first, what they are built on after.
    static let groupOrder = ["SSH", "Networking", "Databases", "Terminal", "Remote desktop", "Editor",
                             "Syntax highlighting", "Artwork", "Swift libraries", "Inside Mermaid"]

    static func load(from bundle: Bundle = .module) throws -> [GlassAcknowledgement] {
        guard let url = bundle.url(forResource: "Acknowledgements", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try JSONDecoder().decode(File.self, from: Data(contentsOf: url)).components
    }

    static func grouped(_ components: [GlassAcknowledgement]) -> [(group: String, components: [GlassAcknowledgement])] {
        Dictionary(grouping: components, by: \.group)
            .map { (group: $0.key, components: $0.value.sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }) }
            .sorted { (groupOrder.firstIndex(of: $0.group) ?? .max, $0.group) < (groupOrder.firstIndex(of: $1.group) ?? .max, $1.group) }
    }
}

struct GlassShellAcknowledgementsView: View {
    @Environment(\.dismiss) private var dismiss
    @State private var components: [GlassAcknowledgement] = []
    @State private var problem: String?
    @State private var search = ""

    private var shown: [GlassAcknowledgement] {
        guard !search.isEmpty else { return components }
        return components.filter {
            $0.name.localizedCaseInsensitiveContains(search) || $0.license.localizedCaseInsensitiveContains(search)
        }
    }

    var body: some View {
        NavigationStack {
            List {
                if let problem {
                    Text(problem).foregroundStyle(.secondary)
                }
                ForEach(GlassAcknowledgements.grouped(shown), id: \.group) { section in
                    Section(section.group) {
                        ForEach(section.components) { component in
                            NavigationLink(value: component) { row(component) }
                        }
                    }
                }
            }
            .searchable(text: $search, prompt: "Name or licence")
            .navigationTitle("Acknowledgements")
            .navigationDestination(for: GlassAcknowledgement.self) { GlassAcknowledgementDetail(component: $0) }
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("Done") { dismiss() }
                        .accessibilityIdentifier("acknowledgements-done")
                }
            }
        }
        #if os(macOS)
        .frame(minWidth: 560, minHeight: 520)
        #endif
        .task {
            guard components.isEmpty else { return }
            do {
                components = try GlassAcknowledgements.load()
            } catch {
                problem = "The acknowledgements are missing from this build. They are also in THIRD-PARTY-NOTICES.md in the source."
            }
        }
    }

    private func row(_ component: GlassAcknowledgement) -> some View {
        VStack(alignment: .leading, spacing: 2) {
            Text(component.name)
            Text([component.license, component.versionLabel].compactMap { $0 }.joined(separator: " · "))
                .font(.caption).foregroundStyle(.secondary)
        }
        .accessibilityElement(children: .combine)
    }
}

private struct GlassAcknowledgementDetail: View {
    let component: GlassAcknowledgement

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 14) {
                VStack(alignment: .leading, spacing: 4) {
                    Text(component.license).font(.headline)
                    if let version = component.versionLabel {
                        Text(version).font(.callout).foregroundStyle(.secondary)
                    }
                    if let note = component.note {
                        Text(note).font(.callout).foregroundStyle(.secondary)
                    }
                    if let source = component.source, let url = URL(string: source) {
                        Link(source, destination: url).font(.callout)
                    }
                }
                ForEach(component.texts, id: \.self) { text in
                    VStack(alignment: .leading, spacing: 6) {
                        if component.texts.count > 1 {
                            Text(text.title).font(.subheadline.weight(.semibold))
                        }
                        Text(text.body)
                            .font(.system(.caption, design: .monospaced))
                            .textSelection(.enabled)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding()
        }
        .navigationTitle(component.name)
    }
}
